using Dapper;
using InovaGed.Application.Common.Database;
using InovaGed.Application.PhysicalArchive.WorkOrders;

namespace InovaGed.Infrastructure.PhysicalArchive;

public sealed class ArchiveWorkOrderService(IDbConnectionFactory factory):IArchiveWorkOrderService,IArchiveWorkOrderTaskService,IArchiveWorkOrderSlaService
{
 public async Task<Guid>CreateAsync(ArchiveWorkOrderCreateCommand c,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await using var tx=await db.BeginTransactionAsync(ct);var id=Guid.NewGuid();var due=c.DueAt??DefaultDue(c.Priority);var number=$"OS-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid():N}"[..20].ToUpperInvariant();await db.ExecuteAsync(new CommandDefinition("insert into ged.archive_work_order(id,tenant_id,order_number,title,description,order_type,priority,subject_type,subject_id,box_id,document_id,control_number,location_expected,location_found,location_target,source_type,source_id,assigned_to,assigned_by,assigned_at,due_at,created_by) values(@id,@TenantId,@number,@Title,@Description,@OrderType,@Priority,@SubjectType,@SubjectId,@BoxId,@DocumentId,@ControlNumber,@LocationExpected,@LocationFound,@LocationTarget,@SourceType,@SourceId,@AssignedTo,case when @AssignedTo is null then null else @UserId end,case when @AssignedTo is null then null else now() end,@due,@UserId)",new{id,number,due,c.TenantId,c.Title,c.Description,c.OrderType,c.Priority,c.SubjectType,c.SubjectId,c.BoxId,c.DocumentId,c.ControlNumber,c.LocationExpected,c.LocationFound,c.LocationTarget,c.SourceType,c.SourceId,c.AssignedTo,c.UserId},tx,cancellationToken:ct));var tasks=Templates(c.OrderType);for(var i=0;i<tasks.Length;i++){var t=tasks[i];await db.ExecuteAsync(new CommandDefinition("insert into ged.archive_work_order_task(tenant_id,work_order_id,title,task_type,display_order,requires_scan,requires_evidence,assigned_to) values(@TenantId,@id,@title,@type,@i,@scan,@evidence,@AssignedTo)",new{c.TenantId,id,title=t.Title,type=t.Type,i=i+1,scan=t.Scan,evidence=t.Evidence,c.AssignedTo},tx,cancellationToken:ct));}await Event(db,tx,c.TenantId,id,null,"WORK_ORDER_CREATED","Ordem de serviço criada",null,null,c.AssignedTo is null?ArchiveWorkOrderStatus.Open:ArchiveWorkOrderStatus.Assigned,c.UserId,ct);await tx.CommitAsync(ct);return id;}
 public async Task<Guid>CreateFromAlertAsync(Guid t,Guid alertId,Guid u,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var x=await db.QuerySingleOrDefaultAsync<SourceRow>(new CommandDefinition("select title,message description,severity priority,subject_type SubjectType,subject_id SubjectId,control_number ControlNumber,location LocationFound from ged.label_alert where tenant_id=@t and id=@alertId and reg_status='A'",new{t,alertId},cancellationToken:ct))??throw new KeyNotFoundException("Alerta não encontrado.");return await CreateAsync(new(t,u,x.Title,ArchiveWorkOrderType.CheckLocation,x.Priority,x.Description,x.SubjectType,x.SubjectId,ControlNumber:x.ControlNumber,LocationFound:x.LocationFound,SourceType:"LABEL_ALERT",SourceId:alertId),ct);}
 public async Task<Guid>CreateFromReconciliationIssueAsync(Guid t,Guid issueId,Guid u,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var x=await db.QuerySingleOrDefaultAsync<SourceRow>(new CommandDefinition("select title,description,severity priority,subject_type SubjectType,subject_id SubjectId,control_number ControlNumber,expected_value LocationExpected,found_value LocationFound from ged.archive_reconciliation_issue where tenant_id=@t and id=@issueId and reg_status='A'",new{t,issueId},cancellationToken:ct))??throw new KeyNotFoundException("Inconsistência não encontrada.");return await CreateAsync(new(t,u,x.Title,ArchiveWorkOrderType.ReconcileIssue,x.Priority,x.Description,x.SubjectType,x.SubjectId,ControlNumber:x.ControlNumber,LocationExpected:x.LocationExpected,LocationFound:x.LocationFound,SourceType:"RECONCILIATION_ISSUE",SourceId:issueId),ct);}
 public async Task<IReadOnlyList<ArchiveWorkOrderListItem>>ListAsync(Guid t,ArchiveWorkOrderFilter f,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return(await db.QueryAsync<ArchiveWorkOrderListItem>(new CommandDefinition("select id,order_number OrderNumber,title,order_type OrderType,priority,status,assigned_to AssignedTo,null::text AssignedName,due_at DueAt,source_type SourceType,location_target LocationTarget,control_number ControlNumber,created_at CreatedAt from ged.archive_work_order where tenant_id=@t and reg_status='A' and (coalesce(@Status,'')='' or status=@Status) and (coalesce(@OrderType,'')='' or order_type=@OrderType) and (coalesce(@Priority,'')='' or priority=@Priority) and (@AssignedTo is null or assigned_to=@AssignedTo) and (coalesce(@Location,'')='' or coalesce(location_target,location_found,location_expected,'') ilike '%'||@Location||'%') and (coalesce(@ControlNumber,'')='' or control_number ilike '%'||@ControlNumber||'%') and (coalesce(@SourceType,'')='' or source_type=@SourceType) and (coalesce(@Due,'')<> 'overdue' or due_at<now()) order by created_at desc limit 1000",new{t,f.Status,f.OrderType,f.Priority,f.AssignedTo,f.Location,f.ControlNumber,f.SourceType,f.Due},cancellationToken:ct))).AsList();}
 public async Task<ArchiveWorkOrderDetails?>GetAsync(Guid t,Guid id,CancellationToken ct){var list=await ListAsync(t,new(),ct);var o=list.FirstOrDefault(x=>x.Id==id);if(o is null)return null;await using var db=await factory.OpenAsync(ct);var extra=await db.QuerySingleAsync<DetailRow>(new CommandDefinition("select description,subject_type SubjectType,subject_id SubjectId,box_id BoxId,document_id DocumentId,location_expected LocationExpected,location_found LocationFound,started_at StartedAt,completed_at CompletedAt,closed_at ClosedAt,close_notes CloseNotes from ged.archive_work_order where tenant_id=@t and id=@id",new{t,id},cancellationToken:ct));var tasks=(await db.QueryAsync<ArchiveWorkOrderTaskItem>(new CommandDefinition("select id,title,description,task_type TaskType,status,display_order DisplayOrder,requires_scan RequiresScan,requires_evidence RequiresEvidence,assigned_to AssignedTo,completed_at CompletedAt,result_notes ResultNotes from ged.archive_work_order_task where tenant_id=@t and work_order_id=@id and reg_status='A' order by display_order",new{t,id},cancellationToken:ct))).AsList();var events=(await db.QueryAsync<ArchiveWorkOrderEventItem>(new CommandDefinition("select id,task_id TaskId,event_type EventType,event_title EventTitle,event_description EventDescription,from_status FromStatus,to_status ToStatus,performed_by PerformedBy,performed_at PerformedAt from ged.archive_work_order_event where tenant_id=@t and work_order_id=@id and reg_status='A' order by performed_at desc",new{t,id},cancellationToken:ct))).AsList();var ev=(await db.QueryAsync<ArchiveWorkOrderEvidenceItem>(new CommandDefinition("select id,task_id TaskId,label_evidence_id LabelEvidenceId,description,attached_by AttachedBy,attached_at AttachedAt from ged.archive_work_order_evidence where tenant_id=@t and work_order_id=@id and reg_status='A' order by attached_at desc",new{t,id},cancellationToken:ct))).AsList();return new(o,extra.Description,extra.SubjectType,extra.SubjectId,extra.BoxId,extra.DocumentId,extra.LocationExpected,extra.LocationFound,extra.StartedAt,extra.CompletedAt,extra.ClosedAt,extra.CloseNotes,tasks,events,ev);}
 public Task AssignAsync(Guid t,Guid id,Guid to,Guid by,DateTimeOffset? due,CancellationToken ct)=>Transition(t,id,by,"ASSIGNED","WORK_ORDER_ASSIGNED","OS atribuída","assigned_to=@to,assigned_by=@by,assigned_at=now(),due_at=coalesce(@due,due_at)",ct,new{to,by,due});
 public Task StartAsync(Guid t,Guid id,Guid u,CancellationToken ct)=>Transition(t,id,u,"IN_PROGRESS","WORK_ORDER_STARTED","Execução iniciada","started_at=coalesce(started_at,now())",ct);
 public Task CompleteAsync(Guid t,Guid id,Guid u,string notes,CancellationToken ct)=>Transition(t,id,u,"COMPLETED","WORK_ORDER_COMPLETED","Execução finalizada","completed_at=now(),completed_by=@u,close_notes=@notes",ct,new{u,notes},true);
 public Task CloseAsync(Guid t,Guid id,Guid u,string notes,CancellationToken ct)=>Transition(t,id,u,"CLOSED","WORK_ORDER_CLOSED","OS encerrada para auditoria","closed_at=now(),closed_by=@u,close_notes=@notes",ct,new{u,notes},true);
 public Task CancelAsync(Guid t,Guid id,Guid u,string reason,CancellationToken ct){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Motivo do cancelamento é obrigatório.");return Transition(t,id,u,"CANCELLED","WORK_ORDER_CANCELLED","OS cancelada","cancellation_reason=@reason",ct,new{reason});}
 async Task Transition(Guid t,Guid id,Guid u,string status,string type,string title,string set,CancellationToken ct,object? more=null,bool requireTasks=false){await using var db=await factory.OpenAsync(ct);await using var tx=await db.BeginTransactionAsync(ct);var old=await db.ExecuteScalarAsync<string?>(new CommandDefinition("select status from ged.archive_work_order where tenant_id=@t and id=@id and reg_status='A' for update",new{t,id},tx,cancellationToken:ct))??throw new KeyNotFoundException();if(requireTasks&&await db.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from ged.archive_work_order_task where tenant_id=@t and work_order_id=@id and reg_status='A' and status<>'COMPLETED'",new{t,id},tx,cancellationToken:ct))>0)throw new InvalidOperationException("Conclua todas as tarefas obrigatórias antes de finalizar.");var p=new DynamicParameters(more);p.Add("t",t);p.Add("id",id);p.Add("u",u);p.Add("status",status);await db.ExecuteAsync(new CommandDefinition($"update ged.archive_work_order set status=@status,{set},updated_at=now(),updated_by=@u where tenant_id=@t and id=@id",p,tx,cancellationToken:ct));await Event(db,tx,t,id,null,type,title,null,old,status,u,ct);await tx.CommitAsync(ct);}
 public async Task CompleteTaskAsync(Guid t,Guid taskId,Guid u,ArchiveWorkOrderTaskResult r,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await using var tx=await db.BeginTransactionAsync(ct);var task=await db.QuerySingleOrDefaultAsync<TaskRow>(new CommandDefinition("select work_order_id WorkOrderId,requires_scan RequiresScan,requires_evidence RequiresEvidence from ged.archive_work_order_task where tenant_id=@t and id=@taskId and reg_status='A'",new{t,taskId},tx,cancellationToken:ct))??throw new KeyNotFoundException();if(task.RequiresScan&&!r.ScanConfirmed)throw new InvalidOperationException("Esta tarefa exige leitura da etiqueta.");if(task.RequiresEvidence&&r.LabelEvidenceId is null)throw new InvalidOperationException("Anexe uma evidência para comprovar a execução física da tarefa.");await db.ExecuteAsync(new CommandDefinition("update ged.archive_work_order_task set status='COMPLETED',completed_at=now(),completed_by=@u,result_notes=@Notes where tenant_id=@t and id=@taskId",new{t,taskId,u,r.Notes},tx,cancellationToken:ct));if(r.LabelEvidenceId is Guid e)await db.ExecuteAsync(new CommandDefinition("insert into ged.archive_work_order_evidence(tenant_id,work_order_id,task_id,label_evidence_id,description,attached_by) values(@t,@WorkOrderId,@taskId,@e,@EvidenceDescription,@u)",new{t,task.WorkOrderId,taskId,e,r.EvidenceDescription,u},tx,cancellationToken:ct));await Event(db,tx,t,task.WorkOrderId,taskId,"WORK_ORDER_TASK_COMPLETED","Tarefa concluída",r.Notes,"PENDING","COMPLETED",u,ct);await tx.CommitAsync(ct);}
 public async Task ReopenTaskAsync(Guid t,Guid taskId,Guid u,string reason,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var order=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("update ged.archive_work_order_task set status='PENDING',completed_at=null,completed_by=null,result_notes=@reason where tenant_id=@t and id=@taskId returning work_order_id",new{t,taskId,reason},cancellationToken:ct))??throw new KeyNotFoundException();await db.ExecuteAsync(new CommandDefinition("insert into ged.archive_work_order_event(tenant_id,work_order_id,task_id,event_type,event_title,event_description,performed_by) values(@t,@order,@taskId,'WORK_ORDER_TASK_REOPENED','Tarefa reaberta',@reason,@u)",new{t,order,taskId,reason,u},cancellationToken:ct));}
 public async Task<ArchiveWorkOrderSlaSummary>GetSummaryAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return await db.QuerySingleAsync<ArchiveWorkOrderSlaSummary>(new CommandDefinition("select count(*) filter(where status in('OPEN','ASSIGNED')) Open,count(*) filter(where status='IN_PROGRESS') InProgress,count(*) filter(where due_at<now() and status not in('CLOSED','CANCELLED')) Overdue,count(*) filter(where priority='CRITICAL' and status not in('CLOSED','CANCELLED')) Critical,count(*) filter(where status='WAITING_VALIDATION') WaitingValidation,count(*) filter(where completed_at>=date_trunc('month',now())) CompletedThisMonth,coalesce(avg(extract(epoch from(completed_at-created_at))/3600) filter(where completed_at is not null),0)::float8 AverageCompletionHours,count(distinct assigned_to) filter(where status not in('CLOSED','CANCELLED')) ActiveOperators from ged.archive_work_order where tenant_id=@t and reg_status='A'",new{t},cancellationToken:ct));}
 public async Task<IReadOnlyList<ArchiveWorkOrderSlaItem>>ListOverdueAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return(await db.QueryAsync<ArchiveWorkOrderSlaItem>(new CommandDefinition("select id,order_number OrderNumber,title,priority,assigned_to AssignedTo,null::text AssignedName,due_at DueAt,extract(epoch from(now()-due_at))/3600 OverdueHours from ged.archive_work_order where tenant_id=@t and due_at<now() and status not in('CLOSED','CANCELLED') and reg_status='A' order by due_at",new{t},cancellationToken:ct))).AsList();}
 static DateTimeOffset DefaultDue(string p)=>p switch{"CRITICAL"=>DateTimeOffset.UtcNow.AddHours(4),"HIGH"=>AddBusinessDays(1),"LOW"=>AddBusinessDays(7),_=>AddBusinessDays(3)};static DateTimeOffset AddBusinessDays(int n){var d=DateTimeOffset.UtcNow;while(n>0){d=d.AddDays(1);if(d.DayOfWeek is not DayOfWeek.Saturday and not DayOfWeek.Sunday)n--;}return d;}
 static (string Title,string Type,bool Scan,bool Evidence)[] Templates(string type)=>type switch{ArchiveWorkOrderType.PrintLabel=>T("Conferir dados da caixa/documento|Gerar etiqueta|Imprimir etiqueta|Ler QR Code para validar|Fotografar etiqueta aplicada|Concluir",3,4),ArchiveWorkOrderType.ReplaceLabel=>T("Localizar objeto físico|Fotografar etiqueta antiga|Gerar nova etiqueta|Aplicar nova etiqueta|Ler QR Code novo|Registrar substituição",4,1),ArchiveWorkOrderType.ReconcileIssue=>T("Revisar inconsistência|Conferir objeto físico|Aplicar correção aprovada|Registrar evidência|Validar cadeia de custódia",-1,3),_=>T("Ler etiqueta no local encontrado|Confirmar localização física|Fotografar estante/prateleira|Atualizar localização ou abrir inconsistência|Concluir conferência",0,2)};static (string Title,string Type,bool Scan,bool Evidence)[] T(string s,int scan,int evidence)=>s.Split('|').Select((x,i)=>(x,$"STEP_{i+1}",i==scan,i==evidence)).ToArray();
 static Task Event(System.Data.Common.DbConnection db,System.Data.Common.DbTransaction tx,Guid t,Guid id,Guid? task,string type,string title,string? desc,string? from,string? to,Guid user,CancellationToken ct)=>db.ExecuteAsync(new CommandDefinition("insert into ged.archive_work_order_event(tenant_id,work_order_id,task_id,event_type,event_title,event_description,from_status,to_status,performed_by) values(@t,@id,@task,@type,@title,@desc,@from,@to,@user); insert into ged.label_custody_event(tenant_id,subject_type,subject_id,control_number,event_type,event_title,event_description,source_table,source_id,location_from,location_to,performed_by) select tenant_id,coalesce(subject_type,'WORK_ORDER'),coalesce(subject_id,id),control_number,@type,@title,@desc,'archive_work_order',id,location_found,location_target,@user from ged.archive_work_order where tenant_id=@t and id=@id",new{t,id,task,type,title,desc,from,to,user},tx,cancellationToken:ct));
 sealed class SourceRow{public string Title{get;set;}="";public string?Description{get;set;}public string Priority{get;set;}="MEDIUM";public string?SubjectType{get;set;}public Guid?SubjectId{get;set;}public string?ControlNumber{get;set;}public string?LocationExpected{get;set;}public string?LocationFound{get;set;}}
 sealed class DetailRow{public string?Description{get;set;}public string?SubjectType{get;set;}public Guid?SubjectId{get;set;}public Guid?BoxId{get;set;}public Guid?DocumentId{get;set;}public string?LocationExpected{get;set;}public string?LocationFound{get;set;}public DateTimeOffset?StartedAt{get;set;}public DateTimeOffset?CompletedAt{get;set;}public DateTimeOffset?ClosedAt{get;set;}public string?CloseNotes{get;set;}}
 sealed class TaskRow{public Guid WorkOrderId{get;set;}public bool RequiresScan{get;set;}public bool RequiresEvidence{get;set;}}
}
